pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_nested_squares(n: i32) -> Polygon {
    let mut polygon = Vec::new();

    for i in 0..n {
        let offset = f64::from(i * 2);
        let size = f64::from(n);
        let ring = vec![
            [offset, offset],
            [offset + size, offset],
            [offset + size, offset + size],
            [offset, offset + size],
        ];
        polygon.push(ring);
    }

    polygon
}

