pub fn parse_n<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let mut args = args.into_iter();
    let _program_name = args.next();

    match args.next() {
        Some(value) => atoi_i32(&value),
        None => 4,
    }
}

fn atoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && is_ascii_space(bytes[index]) {
        index += 1;
    }

    let mut sign = 1i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let mut value = 0i64;
    let mut saw_digit = false;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        saw_digit = true;
        value = value.saturating_mul(10);
        value = value.saturating_add(i64::from(bytes[index] - b'0'));
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    let signed = value.saturating_mul(sign);
    signed.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
}

fn is_ascii_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c)
}

