pub fn build_polygon(n: i32) -> Polygon {
    let mut polygon = Vec::new();

    if n <= 0 {
        return polygon;
    }

    for i in 0..n {
        let offset = f64::from(i) * 2.0;
        let size = f64::from(n);
        let ring = vec![
            [offset, offset],
            [offset + size, offset],
            [offset + size, offset + size],
            [offset, offset + size],
        ];
        polygon.push(ring);
    }

    polygon
}

