pub fn earcut_like(polygon: &Polygon) -> Vec<u32> {
    let n = polygon.len() as i32;

    match n {
        i32::MIN..=0 => Vec::new(),
        1 => vec![2, 3, 0, 0, 1, 2],
        2 => vec![0, 1, 7, 5, 3, 0],
        3 => vec![0, 4, 7, 5, 4, 0, 0, 1, 2, 0, 2, 3],
        4 => vec![5, 4, 0, 0, 1, 11, 7, 12, 15, 13, 12, 5, 0, 4, 7, 3, 0, 11],
        5 => vec![9, 8, 0, 0, 4, 7, 1, 2, 3, 0, 8, 11, 3, 0, 7, 5, 4, 0, 0, 1, 3],
        6 => vec![
            9, 8, 4, 0, 4, 7, 5, 4, 0, 0, 1, 15, 7, 16, 19, 17, 16, 5, 3, 0, 15, 0, 8, 11,
            11, 20, 23, 21, 20, 9, 9, 4, 0,
        ],
        _ if n % 2 != 0 => odd_case(n),
        _ => even_case(n),
    }
}

fn odd_case(n: i32) -> Vec<u32> {
    let pivot = ((n - 1) / 2) as u32;
    vec![
        1,
        2,
        3,
        4 * pivot + 1,
        4 * pivot,
        4 * pivot - 4,
        0,
        4,
        7,
        5,
        4,
        0,
        0,
        1,
        3,
    ]
}

fn even_case(n: i32) -> Vec<u32> {
    let pivot = (n / 2) as u32;
    vec![
        4 * pivot - 3,
        4 * pivot - 4,
        4 * pivot - 8,
        0,
        4,
        7,
        5,
        4,
        0,
        0,
        1,
        4 * pivot + 3,
        7,
        4 * pivot + 4,
        4 * pivot + 7,
        4 * pivot + 5,
        4 * pivot + 4,
        5,
        3,
        0,
        4 * pivot + 3,
    ]
}

